-- ===================================================
-- NOVAS TABELAS
-- ===================================================
CREATE TABLE IF NOT EXISTS base_escolas (
  id text PRIMARY KEY,
  data jsonb NOT NULL,
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS projetos_escola (
  id bigserial PRIMARY KEY,
  escola_id text,
  serie text NOT NULL,
  envio_1 text,
  envio_2 text,
  envio_3 text,
  UNIQUE(escola_id, serie)
);

-- Vincula schools ao base_escolas
ALTER TABLE schools ADD COLUMN IF NOT EXISTS escola_base_id text;

-- ===================================================
-- DADOS: base_escolas
-- ===================================================
ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, updated_at = now();

-- ===================================================
-- DADOS: projetos_escola
-- ===================================================
ON CONFLICT (escola_id, serie) DO UPDATE SET envio_1=EXCLUDED.envio_1, envio_2=EXCLUDED.envio_2, envio_3=EXCLUDED.envio_3;